  React.useEffect(() => {
    const DECAY_INTERVAL = 36e5;
    const DECAY_AMOUNT = 8;
    const COOLDOWN = 6 * 36e5;
    const now2 = Date.now();
    const allCities = ["\u0130stanbul", "Ankara", "\u0130zmir", "Bursa", "Adana", "Antalya", "Konya", "Gaziantep", "Mersin", "Trabzon"];
    let changed = false;
    const updWelf = { ...cityWelfare };
    allCities.forEach((city) => {
      const lastBuild = cityBuildCooldown[city] || 0;
      const timeSinceBuild = now2 - lastBuild;
      if (lastBuild > 0 && timeSinceBuild > COOLDOWN) {
        const decayPeriods = Math.floor((timeSinceBuild - COOLDOWN) / DECAY_INTERVAL);
        if (decayPeriods > 0) {
          const cur = updWelf[city] && updWelf[city].welfare !== void 0 ? updWelf[city].welfare : 75;
          const newVal = Math.max(0, cur - DECAY_AMOUNT * decayPeriods);
          if (newVal !== cur) {
            updWelf[city] = { ...updWelf[city] || {}, welfare: newVal };
            changed = true;
          }
        }
      }
    });
    if (changed) {
      setCityWelfare(updWelf);
      S.save("cityWelfare", updWelf);
    }
  }, []);
