      const bets = S.load("horseBets", []);
      const matchBets = bets.filter((b) => b.matchId === nextMatch.id && !b.settled);
      if (matchBets.length > 0) {
        const outcome = hg > ag ? "home" : ag > hg ? "away" : "draw";
        matchBets.forEach((b) => {
          if (b.pick === outcome) {
            setAllUsers((prev) => prev.map((u) => u.id === b.userId ? { ...u, money: (u.money || 0) + Math.floor(b.amount * b.odds) } : u));
          }
        });
        setHorseBets((prev) => prev.map((b) => matchBets.find((mb) => mb.id === b.id) ? { ...b, settled: true, won: b.pick === outcome, payout: b.pick === outcome ? Math.floor(b.amount * b.odds) : 0 } : b));
        S.save("horseBets", bets.map((b) => matchBets.find((mb) => mb.id === b.id) ? { ...b, settled: true, won: b.pick === outcome } : b));
      }
      addFeed(`\u26BD Lig Ma\xE7\u0131: ${home.name} ${hg}-${ag} ${away.name}`, "sports");
